const express = require('express');
const cors = require('cors');
const pg = require('pg');
require('dotenv').config(); // Ensure .env is configured correctly on Render
const path = require('path');

// --- Logging for server setup ---
console.log('Node.js version:', process.version);
console.log('Starting server setup...');

const app = express();
// Use Render's PORT environment variable, or default to 3000 if not set
const port = process.env.PORT || 3000;
console.log(`Server will attempt to listen on port: ${port}`);

// --- Middleware ---
app.use(cors());
app.use(express.json());
console.log('CORS and JSON middleware applied.');

// --- Database Connection ---
console.log('Attempting to create PG Pool...');
const pool = new pg.Pool({
 connectionString: process.env.DATABASE_URL,
 // Removed the problematic 'types' and 'options' related to timezone functions
 // as they were causing a TypeError when initializing the pool.
 // Relying on default pg and PostgreSQL behavior for timezone handling.
 ssl: {
 // Set rejectUnauthorized to false for development/testing if necessary,
 // but for production, it's recommended to set this to true and provide CA certificates.
 rejectUnauthorized: false
 }
});
console.log('PG Pool created.');

// --- API Routes ---
// Define API routes first.
console.log('Defining API routes...');

// Login Route
app.post('/api/login', async (req, res) => {
 const { email, password } = req.body;
 try {
 console.log('Executing login SQL query...');
 const result = await pool.query(
 'SELECT * FROM businesses WHERE email = $1 AND password = $2',
 [email, password]
 );
 console.log('Login SQL query executed.');
 if (result.rows.length > 0) {
 console.log('Login successful for business ID:', result.rows[0].id);
 res.json({ id: result.rows[0].id, success: true });
 } else {
 console.log('Login failed: Invalid credentials');
 res.status(401).json({ success: false, message: 'Invalid credentials' });
 }
 } catch (err) {
 console.error('Login error:', err.message); // Log only the message
 res.status(500).json({ success: false, message: 'Internal server error during login' });
 }
});
console.log('Login route defined.');

// Get Bookings Route
app.get('/api/bookings/:businessId', async (req, res) => {
 const { businessId } = req.params;

 try {
 console.log(`Fetching data for businessId: ${businessId}`);

 // --- Overview Stats ---
 console.log('Executing overview SQL query...');
 const overviewResult = await pool.query(
 `SELECT
 COUNT(CASE WHEN DATE(booking_date) = CURRENT_DATE THEN 1 END) AS "totalAppointmentsToday",
 COUNT(CASE WHEN DATE(booking_date) >= date_trunc('week', CURRENT_DATE) AND DATE(booking_date) < (date_trunc('week', CURRENT_DATE) + interval '1 week') THEN 1 END) AS "totalAppointmentsThisWeek",
 COUNT(CASE WHEN DATE(booking_date) >= (date_trunc('week', CURRENT_DATE) + interval '1 week') AND DATE(booking_date) < (date_trunc('week', CURRENT_DATE) + interval '2 weeks') THEN 1 END) AS "totalAppointmentsNextWeek"
 FROM bookings
 WHERE business_id = $1 AND booking_date IS NOT NULL`,
 [businessId] // businessId is $1 here
 );
 console.log('Overview query executed successfully.');

 // --- Revenue Stats ---
 console.log('Executing revenue SQL query...');
 const revenueResult = await pool.query(
 `SELECT
 SUM(CASE WHEN DATE(booking_date) BETWEEN (CURRENT_DATE - interval '7 days') AND (CURRENT_DATE - interval '1 day') THEN service_price ELSE 0 END) AS "totalRevenueLastWeek",
 SUM(CASE WHEN DATE(booking_date) BETWEEN date_trunc('week', CURRENT_DATE) AND (date_trunc('week', CURRENT_DATE) + interval '5 days') THEN service_price ELSE 0 END) AS "totalRevenueThisWeek",
 SUM(CASE WHEN DATE(booking_date) BETWEEN date_trunc('month', CURRENT_DATE) AND (date_trunc('month', CURRENT_DATE) + interval '1 month - 1 day') THEN service_price ELSE 0 END) AS "totalRevenueThisMonth"
 FROM bookings
 WHERE business_id = $2 AND booking_date IS NOT NULL AND service_price IS NOT NULL`,
 [businessId, businessId] // businessId is $1 and $2 here
 );
 console.log('Revenue query executed successfully.');

 // --- Bookings Fetch ---
 console.log('Executing bookings fetch SQL query...');
 const bookingsResult = await pool.query(
 `SELECT
 booking_id, client_name, client_phone, client_email, service_name, service_price, booking_date, booking_time, patient_type
 FROM bookings
 WHERE business_id = $1 AND booking_date IS NOT NULL AND booking_time IS NOT NULL AND service_price IS NOT NULL
 ORDER BY booking_date DESC, booking_time DESC NULLS LAST
 LIMIT 100`,
 [businessId]
 );
 console.log(`Bookings fetch query executed. Found ${bookingsResult.rows.length} bookings.`);

 res.json({
 overview: overviewResult.rows[0],
 revenue: revenueResult.rows[0],
 bookings: bookingsResult.rows
 });
 console.log('Successfully sent JSON response for bookings.');

 } catch (err) {
 console.error('Error fetching bookings:', err.message);
 res.status(500).json({ message: `Internal server error fetching bookings. Please check server logs for details.` });
 }
});
console.log('/api/bookings/:businessId route defined.');

// --- Static File Serving ONLY ---
// Serve ONLY static files from the 'public' directory.
// express.static will try to match requests directly to files in the public directory.
// If a file is not found, it will result in a 404.
app.use(express.static(path.join(__dirname, 'public')));
console.log(`Static files from '${path.join(__dirname, 'public')}' will be served ONLY.`);

console.log('Server setup complete, attempting to listen...');
// Start the server
app.listen(port, () => {
 console.log(`EeziBook server is running and listening on port ${port}`);
});

