 <script>
 const API_BASE = ''; // Relative paths for API calls
 const SAST_TIMEZONE = 'Africa/Johannesburg';
 function getDateBoundariesSAST(date = new Date()) {
 const year = date.getFullYear();
 const month = date.getMonth(); // 0-indexed

 const startOfDayUTC = (year, month, day) => {
 // Creates a UTC date object for the start of the specified day
 return new Date(Date.UTC(year, month, day));
 };

 // Get current date/time in SAST
 const nowSAST = new Date(date.toLocaleString('en-ZA', { timeZone: SAST_TIMEZONE }));
 const currentDaySAST = nowSAST.getDate();
 const currentMonthSAST = nowSAST.getMonth();
 const currentYearSAST = nowSAST.getFullYear();
 const currentDayOfWeekJS = nowSAST.getDay(); // Sunday = 0, Monday = 1, ..., Saturday = 6

 // Start of today in UTC
 const startOfToday = startOfDayUTC(currentYearSAST, currentMonthSAST, currentDaySAST);

 // Start of tomorrow in UTC
 const startOfTomorrow = new Date(startOfToday);
 startOfTomorrow.setUTCDate(startOfToday.getUTCDate() + 1);

 // Calculate week boundaries (Monday to Saturday) in SAST, returned as UTC for consistency
 const diffToMonday = currentDayOfWeekJS === 0 ? 6 : currentDayOfWeekJS - 1; // 0 for Sunday, 1 for Monday,...
 const startOfThisWeek = new Date(Date.UTC(currentYearSAST, currentMonthSAST, currentDaySAST - diffToMonday));
 startOfThisWeek.setUTCHours(0, 0, 0, 0); // Set to start of day in UTC

 const startOfNextWeek = new Date(startOfThisWeek);
 startOfNextWeek.setUTCDate(startOfThisWeek.getUTCDate() + 7); // Start of next week (next Monday in UTC)

 // End of next week (Saturday of next week in UTC)
 const endOfNextWeek = new Date(startOfNextWeek);
 endOfNextWeek.setUTCDate(startOfNextWeek.getUTCDate() + 5); // +5 days from next Monday to get to next Saturday
 endOfNextWeek.setUTCHours(23, 59, 59, 999); // End of the day in UTC

 // Month boundaries
 const startOfThisMonth = startOfDayUTC(currentYearSAST, currentMonthSAST, 1); // First day of current month in UTC
 const endOfThisMonth = new Date(Date.UTC(currentYearSAST, currentMonthSAST + 1, 0)); // Last day of current month in UTC
 endOfThisMonth.setUTCHours(23, 59, 59, 999);

 const startOfNextMonth = new Date(Date.UTC(currentYearSAST, currentMonthSAST + 1, 1)); // First day of next month in UTC
 const endOfNextMonth = new Date(Date.UTC(currentYearSAST, currentMonthSAST + 2, 0)); // Last day of next month in UTC
 endOfNextMonth.setUTCHours(23, 59, 59, 999);
 // Last month boundaries
 const startOfLastMonth = new Date(Date.UTC(currentYearSAST, currentMonthSAST - 1, 1)); // First day of last month in UTC
 const endOfLastMonth = new Date(Date.UTC(currentYearSAST, currentMonthSAST, 0)); // Last day of last month in UTC
 endOfLastMonth.setUTCHours(23, 59, 59, 999);

 return {
 startOfToday: startOfToday,
 startOfTomorrow: startOfTomorrow,
 startOfThisWeek: startOfThisWeek,
 startOfNextWeek: startOfNextWeek,
 endOfNextWeek: endOfNextWeek,
 startOfThisMonth: startOfThisMonth,
 endOfThisMonth: endOfThisMonth,
 startOfNextMonth: startOfNextMonth,
 endOfNextMonth: endOfNextMonth,
 startOfLastMonth: startOfLastMonth,
 endOfLastMonth: endOfLastMonth
 };
 }

 function login() {
 console.log("Login function called.");
 const emailInput = document.getElementById('email');
 const passwordInput = document.getElementById('password');
 const errorEl = document.getElementById('loginError'); // Corrected variable name

 const email = emailInput?.value;
 const password = passwordInput?.value;

 if (!email || !password) {
 console.error("Email or password not entered.");
 if (errorEl) {
 errorEl.textContent = 'Please enter both email and password.';
 errorEl.classList.add('show');
 }
 return;
 }

 console.log(`Attempting login for email: ${email}`);
 if (errorEl) errorEl.classList.remove('show');

 fetch(`/api/login`, {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({ email, password })
 })
 .then(res => {
 if (!res.ok) {
 console.error(`Login failed: ${res.status} ${res.statusText}`);
 // Check response text for more specific error messages from backend
 return res.text().then(text => { // <--- Corrected line for error handling
 console.error("Raw API response text:", text);
 throw new Error(`HTTP error! status: ${res.status}. Could not fetch bookings. ${text}`);
 });
 }
 return res.json();
 })
 .then(user => {
 console.log("Login successful, user ID:", user.id);
 localStorage.setItem('businessId', user.id);
 // Clear the login card and show the dashboard
 const loginCard = document.getElementById('loginCard');
 if (loginCard) loginCard.style.display = 'none';
 const dashboard = document.getElementById('dashboard');
 if (dashboard) dashboard.style.display = 'block'; // Show dashboard

 showDashboard();
 })
 .catch(err => {
 console.error("Login catch block:", err);
 // Ensure errorEl is correctly referenced here
 if (errorEl) {
 errorEl.textContent = err.message;
 errorEl.classList.add('show');
 }
 });
 }
 function logout() {
 console.log("Logout function called.");
 localStorage.removeItem('businessId');
 const loginCard = document.getElementById('loginCard');
 if (loginCard) loginCard.style.display = 'block';

 const dashboard = document.getElementById('dashboard');
 if (dashboard) dashboard.style.display = 'none'; // Hide dashboard on logout

 // Clear displayed data
 const todayCount = document.getElementById('todayCount');
 if (todayCount) todayCount.textContent = '0';
 const weekCount = document.getElementById('weekCount');
 if (weekCount) weekCount.textContent = '0';
 const nextWeekCount = document.getElementById('nextWeekCount');
 if (nextWeekCount) nextWeekCount.textContent = '0';
 const revenueLastWeek = document.getElementById('revenueLastWeek');
 if (revenueLastWeek) revenueLastWeek.textContent = 'R0.00'; // Corrected variable name
 const revenueThisWeek = document.getElementById('revenueThisWeek');
 if (revenueThisWeek) revenueThisWeek.textContent = 'R0.00';
 const revenueThisMonth = document.getElementById('revenueThisMonth');
 if (revenueThisMonth) revenueThisMonth.textContent = 'R0.00';

 // Also clear booking tables
 renderBookings('today', []);
 renderBookings('tomorrow', []);
 renderBookings('thisWeek', []);
 renderBookings('nextWeek', []);
 renderBookings('thisMonth', []);
 renderBookings('nextMonth', []);
 renderBookings('longTerm', []);
 }

 function renderBookings(period, bookings) {
 console.log(`Rendering bookings for period: ${period}`);
 const tbody = document.getElementById(`${period}BookingsTableBody`);
 if (!tbody) {
 console.warn(`Table body element not found for period: ${period}`);
 return;
 }

 tbody.innerHTML = '';

 if (bookings.length === 0) {
 tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:40px;color:#666;">No bookings for ${period.replace(/([A-Z])/g, ' $1').toLowerCase()}</td></tr>`;
 console.log(`No bookings for ${period}, displaying placeholder.`);
 } else {
 console.log(`Rendering ${bookings.length} bookings for ${period}.`);
 bookings.forEach(b => {
 const row = tbody.insertRow();

 // Safely format date, default to '-' if invalid or missing
 const dateDisplay = b.booking_date ? new Date(b.booking_date).toLocaleDateString('en-ZA', { year: 'numeric', month: '2-digit', day: '2-digit' }).replace(/\//g, '-') : '-';

 let patientTypeClass = 'private';
 if (b.patient_type === 'Medical Aid') {
 patientTypeClass = 'medical-aid';
 }

 row.innerHTML = `
 <td>${dateDisplay}</td>
 <td>${b.booking_time || '-'}</td>
 <td>${b.client_name || 'N/A'}<br><small style="color:#666;">${b.client_email || ''}</small></td>
 <td>${b.client_phone || '-'}</td>
 <td>${b.service_name || '-'}</td>
 <td>R${Number(b.service_price || 0).toFixed(2)}</td>
 <td><span class="patient-type ${patientTypeClass}">${b.patient_type || 'Private'}</span></td>
 `;
 });
 }
 }

 function toggleSection(idPrefix) {
 console.log(`Toggling section: ${idPrefix}`);
 const content = document.getElementById(`${idPrefix}Content`);
 const icon = document.getElementById(`${idPrefix}Icon`);
 if (content && icon) {
 content.classList.toggle('open');
 icon.classList.toggle('open');
 } else {
 console.warn(`Elements for prefix "${idPrefix}" not found.`);
 }
 }

 function showDashboard() {
 console.log("showDashboard function called.");
 const businessId = localStorage.getItem('businessId');
 if (!businessId) {
 console.log("No businessId found in localStorage. Showing login card.");
 const loginCard = document.getElementById('loginCard');
 if (loginCard) loginCard.style.display = 'block';
 const dashboard = document.getElementById('dashboard');
 if (dashboard) dashboard.style.display = 'none'; // Ensure dashboard is hidden
 return;
 }

 console.log("Business ID found:", businessId);
 const loginCard = document.getElementById('loginCard');
 const dashboard = document.getElementById('dashboard');

 if (loginCard) {
 loginCard.style.display = 'none';
 console.log("Login card hidden.");
 }
 if (dashboard) {
 dashboard.style.display = 'block'; // Show dashboard
 console.log("Dashboard displayed.");
 } else {
 console.error("Dashboard element not found!");
 }

 fetch(`/api/bookings/${businessId}`)
 .then(res => {
 if (!res.ok) {
 console.error(`Login API response not OK. Status: ${res.status}, StatusText: ${res.statusText}`);
 // Log the response text to see what the backend is sending in case of an error
 return res.text().then(text => {
 console.error("Raw API response text:", text);
 throw new Error(`HTTP error! status: ${res.status}. Could not fetch bookings. ${text}`);
 });
 }
 return res.json(); // This line will only be reached if res.ok is true
 })
 .then(data => {
 console.log("Dashboard data received:", data);
 const boundaries = getDateBoundariesSAST();

 // Update counts and revenue with safe checks
 const todayCount = document.getElementById('todayCount');
 if (todayCount) todayCount.textContent = data.overview?.totalAppointmentsToday || '0';

 const weekCount = document.getElementById('weekCount');
 if (weekCount) weekCount.textContent = data.overview?.totalAppointmentsThisWeek || '0';

 const nextWeekCount = document.getElementById('nextWeekCount');
 if (nextWeekCount) nextWeekCount.textContent = data.overview?.totalAppointmentsNextWeek || '0';

 const revenueLastWeek = document.getElementById('revenueLastWeek');
 if (revenueLastWeek) revenueLastWeek.textContent = `R${Number(data.revenue?.totalRevenueLastWeek || 0).toFixed(2)}`;

 const revenueThisWeek = document.getElementById('revenueThisWeek');
 if (revenueThisWeek) revenueThisWeek.textContent = `R${Number(data.revenue?.totalRevenueThisWeek || 0).toFixed(2)}`;

 const revenueThisMonth = document.getElementById('revenueThisMonth');
 if (revenueThisMonth) revenueThisMonth.textContent = `R${Number(data.revenue?.totalRevenueThisMonth || 0).toFixed(2)}`;

 // Render bookings
 const todayBookings = [];
 const tomorrowBookings = [];
 const thisWeekBookings = [];
 const nextWeekBookings = [];
 const thisMonthBookings = [];
 const nextMonthBookings = [];
 const longTermBookings = [];

 if (data.bookings && data.bookings.length > 0) {
 data.bookings.forEach(b => {
 if (!b.booking_date) {
 console.warn("Booking found with no booking_date:", b);
 return;
 }
 try {
 // Attempt to parse date, assuming YYYY-MM-DD format
 const bookingDateParts = b.booking_date.split('-');
 if (bookingDateParts.length === 3) {
 const bookingDateObjUTC = new Date(Date.UTC(
 parseInt(bookingDateParts[0]),
 parseInt(bookingDateParts[1]) - 1, // JS months are 0-indexed
 parseInt(bookingDateParts[2])
 ));
 bookingDateObjUTC.setUTCHours(0,0,0,0); // Set to start of day in UTC

 if (!isNaN(bookingDateObjUTC.getTime())) { // Check if date is valid
 if (bookingDateObjUTC.getTime() >= boundaries.startOfToday.getTime() && bookingDateObjUTC.getTime() < boundaries.startOfTomorrow.getTime()) {
 todayBookings.push(b);
 } else if (bookingDateObjUTC.getTime() >= boundaries.startOfTomorrow.getTime() && bookingDateObjUTC.getTime() < boundaries.startOfNextWeek.getTime()) {
 tomorrowBookings.push(b);
 } else if (bookingDateObjUTC.getTime() >= boundaries.startOfThisWeek.getTime() && bookingDateObjUTC.getTime() < boundaries.startOfNextWeek.getTime()) {
 thisWeekBookings.push(b);
 } else if (bookingDateObjUTC.getTime() >= boundaries.startOfNextWeek.getTime() && bookingDateObjUTC.getTime() <= boundaries.endOfNextWeek.getTime()) {
 nextWeekBookings.push(b);
 } else if (bookingDateObjUTC.getTime() >= boundaries.startOfThisMonth.getTime() && bookingDateObjUTC.getTime() <= boundaries.endOfThisMonth.getTime()) {
 thisMonthBookings.push(b);
 } else if (bookingDateObjUTC.getTime() >= boundaries.startOfNextMonth.getTime() && bookingDateObjUTC.getTime() <= boundaries.endOfNextMonth.getTime()) {
 nextMonthBookings.push(b);
 } else {
 longTermBookings.push(b);
 }
 } else {
 console.warn("Invalid date parsed:", b.booking_date);
 }
 } else {
 console.warn("Unexpected booking_date format:", b.booking_date);
 }
 } catch (dateError) {
 console.error("Error processing date for booking:", b, dateError);
 }
 });
 } else {
 console.log("No bookings array or bookings array is empty.");
 }

 renderBookings('today', todayBookings);
 renderBookings('tomorrow', tomorrowBookings);
 renderBookings('thisWeek', thisWeekBookings);
 renderBookings('nextWeek', nextWeekBookings);
 renderBookings('thisMonth', thisMonthBookings);
 renderBookings('nextMonth', nextMonthBookings);
 renderBookings('longTerm', longTermBookings);
 const bookingsByDateContent = document.getElementById('bookingsByDateContent');
 const bookingsByDateIcon = document.getElementById('bookingsByDateIcon');
 if (bookingsByDateContent && bookingsByDateIcon && data.bookings && data.bookings.length > 0) {
 bookingsByDateContent.classList.add('open');
 bookingsByDateIcon.classList.add('open');
 console.log("Bookings section opened.");
 } else {
 console.log("Bookings section not opened (no bookings or elements missing).");
 }

 // Close any previously opened collapse sections, unless it's the main bookings section we just opened
 document.querySelectorAll('.collapsible-sub-section > .collapsible-content').forEach(content => {
 if (!content.id.includes('bookingsByDateContent')) {
 content.classList.remove('open');
 }
 });
 document.querySelectorAll('.collapsible-sub-section > .collapsible-header .collapse-icon').forEach(icon => {
 if (!icon.id.includes('bookingsByDateIcon')) {
 icon.classList.remove('open');
 }
 });
 })
 .catch(err => {
 console.error('Error loading dashboard data:', err);
 const errMessageEl = document.createElement('p');
 errMessageEl.textContent = `Failed to load dashboard data. Please check console for details or contact support.`;
 errMessageEl.style.color = 'red';
 errMessageEl.style.textAlign = 'center';
 errMessageEl.style.padding = '20px';
 errMessageEl.style.fontSize = '1.1em';
 const dashboard = document.getElementById('dashboard');
 if (dashboard) {
 dashboard.innerHTML = ''; // Clear existing content
 dashboard.appendChild(errMessageEl); // Display error message
 } else {
 console.error("Dashboard element not found to display error message.");
 }
 });
 }

 // Ensure the script runs after the DOM is fully loaded
 document.addEventListener('DOMContentLoaded', () => {
 console.log("DOM fully loaded. Initializing admin page...");
 const loginCard = document.getElementById('loginCard');
 const dashboard = document.getElementById('dashboard');

 if (!loginCard || !dashboard) {
 console.error("Required DOM elements (loginCard, dashboard) not found!");
 return;
 }

 if (localStorage.getItem('businessId')) {
 console.log("Business ID found in localStorage. Attempting to show dashboard.");
 // Ensure dashboard is visible and login card is hidden
 loginCard.style.display = 'none';
 dashboard.style.display = 'block'; // Show dashboard
 showDashboard(); // Call showDashboard to fetch data
 } else {
 console.log("No business ID found. Displaying login card.");
 loginCard.style.display = 'block';
 dashboard.style.display = 'none'; // Ensure dashboard is hidden
 }
 });
 </script>
</body>
</html>
